    parameter tCLK_POST_NS = 60,
    parameter tCLK_PREPARE_NS = 60,
    parameter tHS_PREPARE_NS = 80,
    parameter tWAKEUP_NS = 1000,
    parameter tHS_EXIT_NS = 120,
    parameter tHS_ZERO_NS = 200,
    parameter tHS_TRAIL_NS = 100, 
